import { bedrockText } from '../fixtures/bedrock-event-stream.js';

const checkout = fileURLToPath(new URL('../..', import.meta.url));
const require = createRequire(import.meta.url);
const compiler = require.resolve('typescript/bin/tsc');
const installedModules = path.dirname(path.dirname(path.dirname(compiler)));
// Exact installed help contract, not output generated by a source/private API.
